#!/usr/bin/env bash
set -euox pipefail

function repo_root() {
  git rev-parse --show-toplevel
}

function project_version() {
  # VERSION derived from CHANGELOG and automated release library
  fullVersion=$(<"$(repo_root)/VERSION")
  # Only use base version (strip any suffix, e.g. "-dev" or build number)
  if [[ "$fullVersion" == *-* ]]; then
    echo "${fullVersion%%-*}"
  else
    echo "$fullVersion"
  fi
}

# Create a clean copy of the source code for build
cp -a /src /build
git config --global --add safe.directory /build
cd /build
git clean -fdx || :
# Copy the VERSION file generated by the CI to the build directory
cp /src/VERSION /build/VERSION

# Restore packages
dotnet restore

# test (single run with TRX + coverage)
dotnet build

dotnet test test/test.csproj \
  --logger:"trx;LogFileName=TestResults.trx" \
  --collect:"Code Coverage;Format=Cobertura" \
  --results-directory:"/build/TestResults"

# find TRX
found_trx="$(find /build/TestResults -type f -name '*.trx' | head -n 1 || true)"
if [ -z "$found_trx" ]; then
  echo "ERROR: TRX report was not created."
  find /build/TestResults -maxdepth 4 -type f -print || true
  exit 1
fi

# convert TRX -> JUnit XML
trx2junit "$found_trx"

# normalize paths expected by outer build.sh/Jenkins
found_junit="$(find /build/TestResults -type f -name '*.xml' ! -name '*.cobertura.xml' | head -n 1 || true)"
if [ -z "$found_junit" ]; then
  echo "ERROR: JUnit XML was not created from TRX."
  find /build/TestResults -maxdepth 4 -type f -print || true
  exit 1
fi
cp "$found_junit" /build/TestResults.xml

cp /build/TestResults/*/*.cobertura.xml /build/Coverage.xml

VERSION=$(project_version)
dotnet build api-dotnet.sln --configuration Release /p:AssemblyVersion="$VERSION"

mkdir nugetPackages
dotnet pack -o ./nugetPackages --version-suffix "$VERSION"
